INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('59fb0256-8019-4054-a213-b404d37ac285', '21feff02-016d-46e2-bb9d-c27495133b1b', '11. óra: Összeszámlálási feladatok megoldása', 'Önálló feladatmegoldás rendszerezett felsorolással és faábrával.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "9c644a26-4850-4766-9af6-ad8e86a77052", "text": "Hányféleképpen rakhatunk sorba 4 különböző könyvet a polcon? (4*3*2*1)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "79d636fe-54d6-4ba4-bef9-18516228701b", "text": "Hány 3 jegyű szám képezhető a 7, 8, 9 számjegyekből ha mindegyiket csak egyszer használhatjuk fel?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "7be3c698-ba8e-4e79-b76d-785c4e633ac2", "text": "Az ágrajz utolsó szintjén lévő levelek száma megadja az összes lehetséges kimenetelt.", "type": "true-false", "options": [{"id": "7d937230-6717-4e26-8cdc-c3c4a180f4d4", "text": "Igaz", "isCorrect": true}, {"id": "9635be4d-56fb-4c97-a9d8-f18d9c0e390c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "33b6012b-27a0-492e-a2e0-876371cb6086", "text": "Melyik állítás igaz a valószínűségi kísérletekre?", "type": "multiple-choice", "options": [{"id": "f41833d8-abbc-4a33-ab4a-2e13efcb6ff6", "text": "A lehetséges esetek száma a kedvező és kedvezőtlen esetek összege", "isCorrect": true}, {"id": "0acc1747-db7a-431e-a6a4-6e58dcea74a8", "text": "Mindig csak 1 eset lehetséges", "isCorrect": false}, {"id": "b14c1ffc-71cc-4338-bc99-a556802e0f46", "text": "Sohasem lehet kiszámolni az esetek számát", "isCorrect": false}, {"id": "5eddaaaa-690c-4dba-b5ad-43fdd2cce2b1", "text": "Csak páros szám lehet az eredmény", "isCorrect": false}], "timeLimit": 15}, {"id": "444f30d2-3b97-4b6e-bf3a-aa031c767aae", "text": "Hányféle kétgombócos fagyit választhatunk 3-féle ízből, ha két különböző ízt kérünk?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "95a0f6e9-4554-422b-bc9d-0b7b681e12f9", "text": "Ha egy feldobott pénzérmét kétszer dobunk fel egymás után, a lehetséges kimenetelek száma 4.", "type": "true-false", "options": [{"id": "0790f5e6-e16c-4e83-8680-d05551a7eea9", "text": "Igaz (FF, FI, IF, II)", "isCorrect": true}, {"id": "10ee366e-670a-4bdf-a601-4b52ae669147", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "04db5468-d554-45f8-9052-e84244072a30", "text": "Hány válaszlehetőség van egy 4 opciós feleletválasztós kérdésnél?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e54de88a-5f46-4c6d-bb6e-eaec5fe543e3', '21feff02-016d-46e2-bb9d-c27495133b1b', '12. óra: Számonkérés', 'Az egész számok műveleteiből és az összeszámlálásból tanultak számonkérése (10 kérdés).', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "70a804c0-4f0d-4e46-a942-3bf5099cb1a2", "text": "1. Mennyi (-15) + (+20)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "33ac41be-8420-4a2f-8135-c466055c19c5", "text": "2. Mennyi (-6) * (-8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "48"}, {"id": "78985793-cab4-4683-86ee-3011160663ab", "text": "3. Mennyi (-54) : (+9)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-6"}, {"id": "b5598bfa-4fda-4375-a3cb-8bc4a51c29ca", "text": "4. Melyik szám abszolút értéke nagyobb: |-30| vagy |+20|?", "type": "multiple-choice", "options": [{"id": "4b341555-340e-4d39-a9d8-5861e850749c", "text": "|-30|", "isCorrect": true}, {"id": "f1ad7b32-6cdc-40bb-bea2-c1014f030c2a", "text": "|+20|", "isCorrect": false}, {"id": "e8d6d40d-24dd-45e9-83e0-46be700e436a", "text": "Egyenlőek", "isCorrect": false}, {"id": "cdbba0e1-460e-4429-bece-1667887ce102", "text": "Egyik sem", "isCorrect": false}], "timeLimit": 15}, {"id": "0ce960b6-1351-41ab-93f2-aa0725482704", "text": "5. Mennyi (-3) * (-2) * (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-30"}, {"id": "5f891591-b3ab-408c-9ffa-0f751f67f907", "text": "6. A negatív szám szorzása negatív számmal pozitív eredményt ad.", "type": "true-false", "options": [{"id": "25b1cee3-6789-4751-905a-7f2ec9fefe39", "text": "Igaz", "isCorrect": true}, {"id": "95339b49-0e5b-474d-a05c-46005e9521eb", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a8657f28-4791-4867-9524-7f2887ede54a", "text": "7. Hány különböző sorrendben ülhet le 3 gyerek egy padra?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "1b822f18-0351-460f-a0f3-77f7d519922a", "text": "8. Mennyi (-40) : (-8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "b368fbf6-6fd5-4f62-b1b0-5035133e640e", "text": "9. A nullának nincs ellentettje (vagy önmaga az ellentettje).", "type": "true-false", "options": [{"id": "6f51137c-8bba-4d78-96d1-22262c8eb5eb", "text": "Igaz", "isCorrect": true}, {"id": "afda503d-3bea-4159-a576-a8ba1232bcd6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8b267209-5a17-4816-8a5f-e2d48e426045", "text": "10. Mennyi (-10) + (-20) - (-15)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-15"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('52e519d7-058c-4ae0-add0-c428f8bc5923', '21feff02-016d-46e2-bb9d-c27495133b1b', '13. óra: Osztó, többszörös', 'Osztó, többszörös fogalma, osztópárok meghatározása.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "75982658-1928-43ab-92fc-f09d57d8ca2b", "text": "Mit nevezünk egy ''a'' természetes szám osztójának?", "type": "multiple-choice", "options": [{"id": "f558c0b5-02f8-4d53-b542-7e86ffcf9dd4", "text": "Azt a ''b'' számot, amellyel ''a''-t elosztva a maradék 0", "isCorrect": true}, {"id": "0e08db44-463f-4809-94b1-7c9d410ba21e", "text": "Azt a számot, amit ''a''-hoz hozzáadunk", "isCorrect": false}, {"id": "7d5bdff7-96a9-449d-8569-88789250ee14", "text": "Azt a számot, ami nagyobb ''a''-nál", "isCorrect": false}, {"id": "9f012288-e0f7-4ea3-8e13-2e0f128667ac", "text": "Minden páratlan számot", "isCorrect": false}], "timeLimit": 15}, {"id": "f434968e-caf4-4dfd-9c6d-7fa66bf693cf", "text": "Az 1 minden természetes számnak osztója.", "type": "true-false", "options": [{"id": "b938a7c5-8008-4f0a-8629-cb13ac03c7d7", "text": "Igaz", "isCorrect": true}, {"id": "3ed976e7-4dc8-47ca-a3cf-32ddee8072b2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "de5454ab-f115-4d33-bbc5-0be3127be5c8", "text": "Hány osztója van a 12-nek? (1, 2, 3, 4, 6, 12)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "a815e369-f7c2-42c4-9eec-f268de974c02", "text": "Melyik szám a 15 többszöröse az alábbiak közül?", "type": "multiple-choice", "options": [{"id": "41f7184f-7a10-4b22-84e1-4c5aa5833559", "text": "45", "isCorrect": true}, {"id": "8e435969-17ab-49f8-aaa9-e1fa7ff3bfdb", "text": "5", "isCorrect": false}, {"id": "9cc3664c-8f9e-4427-a105-ef85be35c847", "text": "3", "isCorrect": false}, {"id": "2af68c88-5c91-4516-a626-82626458b152", "text": "10", "isCorrect": false}], "timeLimit": 15}, {"id": "30708af8-c1db-4ef1-a3d6-342158db343c", "text": "Minden számnak végtelen sok többszöröse van.", "type": "true-false", "options": [{"id": "a6d1946d-f922-4e12-b49c-84b03b89c198", "text": "Igaz", "isCorrect": true}, {"id": "bd68c20e-063a-4d9b-b5be-d76b89162173", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "db605852-c72a-4608-aaa7-289fe55d450f", "text": "Mi a 20 legkisebb pozitív osztója?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "da367fed-24af-4094-8a89-0b77bb952849", "text": "Mi a 20 legnagyobb osztója önmagán kívül?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('9d8e2747-6d71-43ac-89ca-2b2fd3adb8af', '21feff02-016d-46e2-bb9d-c27495133b1b', '14. óra: Számolás maradékokkal', 'Az osztási maradék fogalma, paritás vizsgálata, összeg maradéka.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "9b95932c-fd10-4254-ac2f-61256b3eeb23", "text": "Mennyi a maradék, ha 23-at elosztjuk 5-tel? (23 = 4*5 + 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "11595972-8514-4863-a48f-f97feeaf1a69", "text": "Egy számot 4-gyel elosztva a lehetséges maradékok: 0, 1, 2, 3.", "type": "true-false", "options": [{"id": "2de0dda0-9fa3-4bbe-bfbd-fed8c206daae", "text": "Igaz", "isCorrect": true}, {"id": "5d98c338-ba6a-4759-ab30-e46d13d3e861", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d82e103f-3fb3-4067-9972-a190aa560f5d", "text": "Milyen maradékot ad 2-vel osztva minden páratlan szám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "b443007b-5513-4d24-8202-edc394632d55", "text": "Két páratlan szám összege mindig páros szám.", "type": "true-false", "options": [{"id": "26f387e8-4b4d-46c7-98cd-01135f8f8ad6", "text": "Igaz (páratlan + páratlan = páros)", "isCorrect": true}, {"id": "9db53af5-9720-4260-8b14-48f9be25f0ab", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c010ca46-8e4a-48ff-bdac-5330ca1d97ee", "text": "Mennyi a maradék 37 : 10 esetén?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "fb8a1df7-a10f-4db5-825f-775fd438cf86", "text": "Két páros szám szorzata mindig páros szám.", "type": "true-false", "options": [{"id": "73c325f7-ad8e-4001-b6fc-da51d8d5fb64", "text": "Igaz", "isCorrect": true}, {"id": "36b8ae29-a7d1-41c2-a330-3df7086412d7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "dfcd2f8f-5f7d-4b11-8c24-4be38599d595", "text": "Melyik szám ad 0 maradékot 3-mal osztva?", "type": "multiple-choice", "options": [{"id": "095382ac-4b1f-4316-9ad1-46220717b7f5", "text": "15", "isCorrect": true}, {"id": "fb7cc852-84ff-4eed-a25c-1031ffbdead8", "text": "16", "isCorrect": false}, {"id": "e7ace081-037b-4bea-91b3-9d98a1909be7", "text": "17", "isCorrect": false}, {"id": "142f2ef1-b61f-4ecd-9896-91c6e4be833b", "text": "19", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e90af3de-4dc3-4037-8e89-9bbe2f8e8d0d', '21feff02-016d-46e2-bb9d-c27495133b1b', '15. óra: Hány osztója van?', 'Természetes számok csoportosítása osztóik száma alapján, prímek és összetett számok.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "e0c78251-5c78-4946-bb31-121ac71a3eba", "text": "Hogyan nevezzük azokat a számokat, amelyeknek pontosan 2 osztójuk van (1 és önmaga)?", "type": "multiple-choice", "options": [{"id": "33ca41e0-53ec-4541-a171-58b32a4243dd", "text": "Prímszámok (prímek)", "isCorrect": true}, {"id": "e139b927-764a-48d5-98b2-c7a6fb2d4e8d", "text": "Összetett számok", "isCorrect": false}, {"id": "0c8eb657-8d95-45f2-afeb-8dee1afac11a", "text": "Páros számok", "isCorrect": false}, {"id": "398b3c5e-f4f1-452e-b0da-1de2974e0e68", "text": "Negatív számok", "isCorrect": false}], "timeLimit": 15}, {"id": "c5a0ee89-44a3-4d6b-838e-c25548b47716", "text": "Az 1 prímszám.", "type": "true-false", "options": [{"id": "dc53173c-9594-42dd-9a52-84a9260983dc", "text": "Igaz", "isCorrect": false}, {"id": "96419825-aea9-44f7-b69a-694d395e8ff6", "text": "Hamis (az 1 sem nem prím, sem nem összetett)", "isCorrect": true}], "timeLimit": 15}, {"id": "9af25206-c7cf-4e63-a157-0c0e53a54ae3", "text": "Melyik a legkisebb prímszám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "0fd609dd-53c7-4200-8a9e-3fb01f7fc9f5", "text": "Melyik az egyetlen páros prímszám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "324cae3e-a88e-446c-aac9-fa1e95dbad13", "text": "Azokat a számokat, amelyeknek 2-nél több osztójuk van, összetett számoknak nevezzük.", "type": "true-false", "options": [{"id": "3213bef3-bff7-415c-a297-d0a145f77054", "text": "Igaz", "isCorrect": true}, {"id": "a1ab02c3-9621-44d3-8c29-0edb0a00444f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2c378e67-e26d-4a2c-8f7a-b6f7e321b11d", "text": "Hány osztója van a 7-nek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "432c9e17-2394-411d-92fa-9fb1f517fa00", "text": "Melyik prím az alábbiak közül?", "type": "multiple-choice", "options": [{"id": "099a82eb-148a-45b7-a9ee-90d4ac06f9f2", "text": "13", "isCorrect": true}, {"id": "db6ed272-4d4b-4129-9566-ba6c853f14f9", "text": "9", "isCorrect": false}, {"id": "b87a6723-4b52-4003-ba91-a5642adfbda2", "text": "15", "isCorrect": false}, {"id": "77b43a2c-6e95-4c35-8c99-af1d540c7d70", "text": "21", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('8742db72-c3ad-4901-928b-6bafd43e5215', '21feff02-016d-46e2-bb9d-c27495133b1b', '16. óra: Feladatok az osztók számának meghatározására, számolás maradékokkal', 'Szöveges feladatok az osztókról és maradékokról.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "e94f7214-e497-4f7d-9151-ac6799ce1fc7", "text": "Hány osztója van a 9-nek? (1, 3, 9)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "a55fd2bd-70de-4c0a-a595-69a309eb4d43", "text": "A négyzetszámoknak páratlan számú osztójuk van.", "type": "true-false", "options": [{"id": "fdaea6be-37da-4f2f-a0b4-6186a9ba4c37", "text": "Igaz (pl. 9-nek 3 osztója van: 1, 3, 9)", "isCorrect": true}, {"id": "7ac429fe-7368-4bbc-be24-3dc3b34ef9df", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a4c99164-b0db-44df-92c3-1fdb029fa0ee", "text": "Ha 25 alma van és 4 gyerek között egyenlően elosztjuk, hány alma marad a kosárban?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "512fffa4-ae64-4568-8367-d59a36122780", "text": "Hány prímszám van 10 és 20 között? (11, 13, 17, 19)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "1c13712e-da4c-4e38-9b4e-a84795777c20", "text": "Melyik szám összetett szám az alábbiak közül?", "type": "multiple-choice", "options": [{"id": "0fa1f5ce-e1f3-4406-a851-e00cb24c023c", "text": "27 (osztói: 1,3,9,27)", "isCorrect": true}, {"id": "40c9653e-51d0-4ffc-b748-9483f7b21b42", "text": "23", "isCorrect": false}, {"id": "db77adf1-a66c-42ec-84d5-acee15723a36", "text": "29", "isCorrect": false}, {"id": "ac534a14-556a-456b-9056-6175c6b27bc1", "text": "31", "isCorrect": false}], "timeLimit": 15}, {"id": "3b6ff66c-6b8f-4ea5-bf74-510160ea8ab2", "text": "Minden páratlan szám prímszám.", "type": "true-false", "options": [{"id": "60ed58f1-d766-4fb1-bb71-5ba1fab487fd", "text": "Igaz", "isCorrect": false}, {"id": "c6b2f85f-7856-4646-9116-6ed995c65962", "text": "Hamis (pl. 9, 15, 21 nem prím)", "isCorrect": true}], "timeLimit": 15}, {"id": "3aa6bce4-f87b-4006-b7e8-a9c82ba1d2b7", "text": "Mennyi a legkisebb kétjegyű prímszám?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
