INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('488ee19a-4e93-44de-9d0a-a54050d75935', '21feff02-016d-46e2-bb9d-c27495133b1b', '18. óra: Oszthatóság 3-mal és 9-cel', 'A számjegyek összegén alapuló oszthatósági szabályok.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "6462cd7c-bf56-42ce-8838-c28ea6d8691b", "text": "Mikor osztható egy szám 3-mal?", "type": "multiple-choice", "options": [{"id": "aa3fb7b2-e117-4b05-a6ba-0228f9747459", "text": "Ha a számjegyeinek összege osztható 3-mal", "isCorrect": true}, {"id": "2b6b212f-da9f-448a-8856-8b84acc75e42", "text": "Ha 3-ra végződik", "isCorrect": false}, {"id": "a8e0d6f5-5244-4179-9b9c-a52ac74af415", "text": "Ha páratlan", "isCorrect": false}, {"id": "be2a00cb-e511-4df8-a963-6dc83e36e3c5", "text": "Ha az utolsó számjegye 3, 6 vagy 9", "isCorrect": false}], "timeLimit": 15}, {"id": "f425c180-dfdd-45e8-9522-f0ea30182c5d", "text": "Mikor osztható egy szám 9-cel?", "type": "multiple-choice", "options": [{"id": "b4c64b38-0c94-4497-b187-ac38ad5c6872", "text": "Ha a számjegyeinek összege osztható 9-cel", "isCorrect": true}, {"id": "0fb2d975-afbd-4904-8aef-81e791e38313", "text": "Ha 9-re végződik", "isCorrect": false}, {"id": "a0daeb48-76c0-437e-a1b3-737c11c3a380", "text": "Ha 3-ra végződik", "isCorrect": false}, {"id": "53cfc26a-fda0-4453-ac0a-f346921bb488", "text": "Ha páros", "isCorrect": false}], "timeLimit": 15}, {"id": "34be66e9-addd-41af-a17e-77e6e86e08eb", "text": "Mennyi a 243 számjegyeinek összege (2+4+3)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "0f437792-0982-4b9c-89ea-e5ddc11180c0", "text": "A 243 osztható 3-mal és 9-cel is.", "type": "true-false", "options": [{"id": "6ef05ea2-16ea-40af-842f-b5db16793d57", "text": "Igaz", "isCorrect": true}, {"id": "78fa4e69-5778-4e85-8f0d-91fe865b5418", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f3379181-7cbe-410c-88cc-7d48606bf5cf", "text": "Ha egy szám osztható 9-cel, akkor 3-mal is osztható.", "type": "true-false", "options": [{"id": "cb3a2e93-0932-4979-b3f2-5747b37bd080", "text": "Igaz", "isCorrect": true}, {"id": "d255b7d1-4b4e-41e3-9ed5-61fd105cd441", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5aa920ec-29b3-4dcb-adb8-e8e996350b75", "text": "Osztható-e a 124 3-mal? (számjegyösszeg: 1+2+4=7)", "type": "true-false", "options": [{"id": "a338af34-b8b4-47b6-a2ca-5130af91dedd", "text": "Igaz", "isCorrect": false}, {"id": "e1e49e42-b19c-48d2-bc7a-c3d4e5d96b36", "text": "Hamis", "isCorrect": true}], "timeLimit": 15}, {"id": "36856146-87fe-4ce3-9b82-eafd0b7fb7a3", "text": "Melyik számjegyet kell az X helyére írni a 51X számban, hogy osztható legyen 9-cel? (5+1+X=9)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('4e590a4a-89a2-452d-abec-2e9c6d388d7e', '21feff02-016d-46e2-bb9d-c27495133b1b', '19. óra: Oszthatóság 4-gyel és 100-zal', 'Oszthatósági szabály az utolsó két számjegy alapján.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "efccae00-d1c0-47ec-a06b-cb2b35f5d1a1", "text": "Mikor osztható egy szám 4-gyel?", "type": "multiple-choice", "options": [{"id": "fc129899-d494-42d0-a71f-0aa6fc17e956", "text": "Ha az utolsó két számjegyéből képzett kétjegyű szám osztható 4-gyel (vagy 00)", "isCorrect": true}, {"id": "fbca370e-d795-4a14-bb68-9e62b887e0ec", "text": "Ha 4-re végződik", "isCorrect": false}, {"id": "a4e34ac5-1852-4e8e-bbb8-554135941298", "text": "Ha a számjegyek összege 4", "isCorrect": false}, {"id": "f62c0d90-57c0-4fa3-8eec-9c4988951a82", "text": "Ha páros", "isCorrect": false}], "timeLimit": 15}, {"id": "6a1da071-7f86-473a-b0a4-1db58932bd5b", "text": "Mikor osztható egy szám 100-zal?", "type": "multiple-choice", "options": [{"id": "cc5a9619-6c68-4734-86be-769bc1e33ee3", "text": "Ha az utolsó két számjegye 00", "isCorrect": true}, {"id": "2c053936-7072-426a-ba70-a989357bd74d", "text": "Ha 100-ra végződik", "isCorrect": false}, {"id": "838e54c3-168b-4bdd-987a-fcbb19365957", "text": "Ha 0-ra végződik", "isCorrect": false}, {"id": "53e4ac6d-aa29-4184-bbc9-d7e64c26db72", "text": "Ha páros", "isCorrect": false}], "timeLimit": 15}, {"id": "41a9815a-d650-4cc8-b365-03bb069f0086", "text": "A 316 osztható 4-gyel (mert 16 osztható 4-gyel).", "type": "true-false", "options": [{"id": "cfbdfaf1-914e-4ad2-987a-19f95ceeb80a", "text": "Igaz", "isCorrect": true}, {"id": "12b3d4a5-6a14-49e7-ae47-12c3568409e0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "52f59400-8019-4180-a1f8-d18ec9be02e1", "text": "A 7500 osztható 100-zal és 4-gyel is.", "type": "true-false", "options": [{"id": "3baec902-8958-4754-a148-5b4cde95