INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('bc5c2635-2609-4bb1-97e3-bccdbf591285', '21feff02-016d-46e2-bb9d-c27495133b1b', '20. óra: Összetett oszthatósági szabályok', 'Új oszthatósági szabályok alkotása (pl. 6-tal való oszthatóság).', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "9a574a2a-306a-4c30-aded-5b6bbfd0df0c", "text": "Mikor osztható egy szám 6-tal?", "type": "multiple-choice", "options": [{"id": "8252eab6-e0af-4930-9ac4-9327e13e7dab", "text": "Ha 2-vel és 3-mal is osztható egyszerre (páros és a számjegyösszeg 3-mal osztható)", "isCorrect": true}, {"id": "13ba271e-37a0-44a3-b64c-84c5b8d8be28", "text": "Ha 6-ra végződik", "isCorrect": false}, {"id": "1d1192c0-32de-4f39-88e7-7ea8dd2b705a", "text": "Ha a számjegyek összege 6", "isCorrect": false}, {"id": "11990987-ef0f-423f-be31-89ee444cf811", "text": "Ha 12-vel osztható", "isCorrect": false}], "timeLimit": 15}, {"id": "b9f9b65c-150c-4ca5-8584-2e6a415a7254", "text": "Mikor osztható egy szám 15-tel?", "type": "multiple-choice", "options": [{"id": "9fd070c1-a923-46fd-88de-8c6152fc57dc", "text": "Ha 3-mal és 5-tel is osztható egyszerre", "isCorrect": true}, {"id": "3d68103b-2e2e-4969-8c09-c59c6edb881f", "text": "Ha 15-re végződik", "isCorrect": false}, {"id": "63e2088b-5a9a-4d5f-989e-ba62b4d69e0b", "text": "Ha páratlan", "isCorrect": false}, {"id": "50bf101e-fdcd-428d-a5f8-08b7b846e2bf", "text": "Ha 5-tel osztható", "isCorrect": false}], "timeLimit": 15}, {"id": "1e7d871e-fc75-405d-8190-3c62d076802d", "text": "A 132 osztható 6-tal (páros és 1+3+2=6).", "type": "true-false", "options": [{"id": "98c8a1b7-cdc2-409e-afcb-765ab31ca287", "text": "Igaz", "isCorrect": true}, {"id": "438027b7-8223-4a84-a057-a685a2546e9f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "fe29c9ce-fdb0-4d75-9e28-b6f623d3a266", "text": "A 45 osztható 15-tel.", "type": "true-false", "options": [{"id": "315d33c9-2bd8-4